pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 tokenId) public {
        // Initialize the contract by calling initialize (needed for getRoyalties to work)
        // We need to set up a minimal state: deploy a proxy or call initialize directly?
        // The contract C is an upgradeable contract, but we are using the implementation directly.
        // To make it work, we can call initialize with dummy values.
        // Since the test is on the implementation, we need to manually set the initialized flag.
        // However, we cannot access internal storage. Instead, we can use the fact that
        // initializeRoyalties is called internally by initialize, and it sets initilaized = true.
        // We can call initialize via the public function.
        // But we also need the phiFactoryContract to be set, etc.
        // To simplify, we can directly call initialize on the implementation.
        // But phiFactoryContract is used in many places. For a minimal test, we can mock it.
        // However, we are not allowed to import other contracts. So we need to work with the existing contract.
        // The easiest way is to deploy a small helper that acts as a phiFactory, but that would require a new contract.
        // Since the test must be standalone, we can use vm.mockCall to mock the phiFactory.
        // But the rule only involves getRoyalties, which does not call phiFactory.
        // The only dependency is that the contract must be initialized (initilaized = true).
        // We can call initialize on the contract with dummy parameters.
        // However, initialize is external and initializer, so we can call it once.
        // But it requires protocolFeeDestination_ which is used for initializeRoyalties.
        // We can pass any address.
        vm.assume(tokenId < 10000); // avoid overflow in fuzzing
        // Initialize the contract
        c.initialize(0, 0, "test", address(this));
        // Now getRoyalties should work
        ICreatorRoyaltiesControl.RoyaltyConfiguration memory result = c.getRoyalties(tokenId);
        // The property: if the token has a custom royalty set, then result equals that custom setting.
        // Otherwise, result equals the default (500 BPS, royaltyRecipient = address(this) passed as protocolFeeDestination).
        // But we cannot know if a custom royalty was set because there is no public getter for the mapping.
        // However, we can set a custom royalty for this tokenId and then check.
        // We need to call updateRoyalties but it requires onlyArtCreator, so we need to be the artist.
        // Since we are the owner (after initialize), we can use c.transferOwnership to get pendingOwner, then accept.
        // But the test is simple: we can check that for a tokenId that we set, the result matches.
        // For this test, we will set a custom royalty and verify it returns correctly.
        // Set a custom royalty
        ICreatorRoyaltiesControl.RoyaltyConfiguration memory config = 
            ICreatorRoyaltiesControl.RoyaltyConfiguration({royaltyBPS: 250, royaltyRecipient: address(0x123)});
        // We need to be the artist to call updateRoyalties. Since the contract is owned by this test contract,
        // and the artist field in artData is not set, we can call the function directly?
        // updateRoyalties checks onlyArtCreator, which reads phiFactoryContract.artData(tokenId).artist.
        // Since phiFactoryContract is not set (it's address(0) after initialize?), we cannot call it.
        // Therefore, we cannot set custom royalties via the public interface without a proper factory.
        // But the bug is in getRoyalties: it ignores the per-token config entirely.
        // So we need a way to prove that for any tokenId, the returned value is always the default,
        // even if a custom configuration was stored. But we cannot store a custom configuration.
        // However, the difference does not require us to set a custom config; the mutant always returns default.
        // The rule should be: for any tokenId, getRoyalties returns the default (500, royaltyRecipient).
        // But in the reference, if no custom config is set, it also returns default.
        // The difference only appears when a custom config exists. Since we cannot create one,
        // the test cannot distinguish P and M. This is a problem.
        // To solve, we must be able to set a custom royalty. We can do that by calling updateRoyalties
        // after setting up the phiFactoryContract to return a dummy artist that matches msg.sender.
        // We can use vm.mockCall to mock the phiFactoryContract.artData call.
        // Let's assume phiFactoryContract is set during initialize (it's set to msg.sender).
        // So after initialize, phiFactoryContract = msg.sender (this test contract).
        // But our test contract address does not have the artData function. So we need to mock it.
        // We can use vm.mockCall to make phiFactoryContract.artData return a specific artist.
        // Since phiFactoryContract is an interface, we can mock the call for our own address.
        // Steps:
        // 1. Initialize (phiFactoryContract = address(this))
        // 2. Use vm.mockCall to mock the artData function of this contract.
        vm.mockCall(
            address(c.phiFactoryContract()), // This is address(this) after initialize
            abi.encodeWithSelector(IPhiFactory.artData.selector, tokenId),
            abi.encode(IPhiFactory.ArtData({
                credId: 0,
                credCreator: address(0),
                credChainId: 0,
                verificationType: "",
                uri: "",
                artAddress: address(0),
                tokenId: 0,
                artist: address(this), // We are the artist
                receiver: address(0),
                royalties: ICreatorRoyaltiesControl.RoyaltyConfiguration(0, address(0)),
                maxSupply: 0,
                mintFee: 0,
                startTime: 0,
                endTime: 0,
                numberMinted: 0,
                soulBounded: false
            }))
        );
        // Now we can call updateRoyalties as the owner (and artist)
        c.updateRoyalties(tokenId, config);
        // Now getRoyalties should return the custom config in P, but default in M.
        ICreatorRoyaltiesControl.RoyaltyConfiguration memory resultAfter = c.getRoyalties(tokenId);
        // The property: resultAfter equals the custom config we set.
        assertTrue(
            resultAfter.royaltyBPS == config.royaltyBPS && 
            resultAfter.royaltyRecipient == config.royaltyRecipient,
            "getRoyalties should return custom per-token configuration"
        );
    }
}

